const queueEnrollments = `-- name: QueueEnrollments :exec
UPDATE triggered_enrollments e SET state = 'queued', delivery_id = d.id, updated_at = $1
FROM broadcast_deliveries d
WHERE e.workspace_id = $2 AND e.broadcast_id = $3 AND e.contact_id = ANY($4::uuid[]) AND e.state = 'waiting'
  AND d.workspace_id = e.workspace_id AND d.broadcast_id = e.broadcast_id AND d.contact_id = e.contact_id
`

type QueueEnrollmentsParams struct {
	Now         time.Time
	WorkspaceID uuid.UUID
	BroadcastID uuid.UUID
	ContactIds  []uuid.UUID
}

func (q *Queries) QueueEnrollments(ctx context.Context, arg QueueEnrollmentsParams) error {
	_, err := q.db.Exec(ctx, queueEnrollments,
		arg.Now,
		arg.WorkspaceID,
		arg.BroadcastID,
		arg.ContactIds,
	)
	return err
}

const removeEnrollment = `-- name: RemoveEnrollment :execrows
UPDATE triggered_enrollments SET state = 'skipped', skip_reason = 'removed', updated_at = $1
WHERE workspace_id = $2 AND broadcast_id = $3 AND contact_id = $4 AND state = 'waiting'
`

type RemoveEnrollmentParams struct {
	Now         time.Time
	WorkspaceID uuid.UUID
	BroadcastID uuid.UUID
	ContactID   uuid.UUID
}

func (q *Queries) RemoveEnrollment(ctx context.Context, arg RemoveEnrollmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, removeEnrollment,
		arg.Now,
		arg.WorkspaceID,
		arg.BroadcastID,
		arg.ContactID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const skipEnrollments = `-- name: SkipEnrollments :exec
UPDATE triggered_enrollments e SET state = 'skipped', skip_reason = r.reason, updated_at = $1
FROM (SELECT unnest($4::uuid[]) AS contact_id, unnest($5::text[]) AS reason) r
WHERE e.workspace_id = $2 AND e.broadcast_id = $3 AND e.contact_id = r.contact_id AND e.state = 'waiting'
`

type SkipEnrollmentsParams struct {
	Now         time.Time
	WorkspaceID uuid.UUID
	BroadcastID uuid.UUID
	ContactIds  []uuid.UUID
	Reasons     []string
}

func (q *Queries) SkipEnrollments(ctx context.Context, arg SkipEnrollmentsParams) error {
	_, err := q.db.Exec(ctx, skipEnrollments,
		arg.Now,
		arg.WorkspaceID,
		arg.BroadcastID,
		arg.ContactIds,
		arg.Reasons,
	)
	return err
}

const triggeredCandidates = `-- name: TriggeredCandidates :many
SELECT c.id AS contact_id, c.name, c.attributes, c.blocked, c.locale,
       coalesce((SELECT e.email FROM contact_emails e WHERE e.workspace_id = c.workspace_id AND e.contact_id = c.id
                 ORDER BY e.position LIMIT 1), '')::text AS email,
       EXISTS (SELECT 1 FROM inbox_mail_optouts o WHERE o.workspace_id = c.workspace_id AND o.inbox_id = $1 AND o.contact_id = c.id)::bool AS stopped,
       coalesce(sub.list_id, '00000000-0000-0000-0000-000000000000'::uuid)::uuid AS list_id, coalesce(sub.email, '')::text AS list_email,
       broadcast_audience_matches(c.attributes, c.locale, $2::jsonb, $3::text[])::bool AS matches
FROM contacts c
LEFT JOIN LATERAL (
    SELECT s.list_id, s.email FROM list_subscriptions s
    WHERE s.workspace_id = c.workspace_id AND s.contact_id = c.id AND s.list_id = ANY($4::uuid[]) AND s.state = 'subscribed'
    ORDER BY array_position($4::uuid[], s.list_id)
    LIMIT 1
) sub ON true
WHERE c.workspace_id = $5 AND c.id = ANY($6::uuid[])
`

type TriggeredCandidatesParams struct {
	InboxID     uuid.UUID
	Conditions  []byte
	Locales     []string
	ListIds     []uuid.UUID
	WorkspaceID uuid.UUID
	ContactIds  []uuid.UUID
}

type TriggeredCandidatesRow struct {
	ContactID  uuid.UUID
	Name       string
	Attributes []byte
	Blocked    bool
	Locale     *string
	Email      string
	Stopped    bool
	ListID     uuid.UUID
	ListEmail  string
	Matches    bool
}

func (q *Queries) TriggeredCandidates(ctx context.Context, arg TriggeredCandidatesParams) ([]TriggeredCandidatesRow, error) {
	rows, err := q.db.Query(ctx, triggeredCandidates,
		arg.InboxID,
		arg.Conditions,
		arg.Locales,
		arg.ListIds,
		arg.WorkspaceID,
		arg.ContactIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TriggeredCandidatesRow
	for rows.Next() {
		var i TriggeredCandidatesRow
		if err := rows.Scan(
			&i.ContactID,
			&i.Name,
			&i.Attributes,
			&i.Blocked,
			&i.Locale,
			&i.Email,
			&i.Stopped,
			&i.ListID,
			&i.ListEmail,
			&i.Matches,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
